insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position) values ('4431eb1f-361d-4afa-bd58-24ada8e7fef0', 'primer-bocado', 'Primer bocado', 'Sin fuego o con microondas · 100 % seco', 'El nivel 1. Todo llega seco y listo para la despensa: tú solo pones agua. Nada de fuegos, como mucho un microondas.', 1, 'chef', '/demo/products/wraps-1.jpg', 1) on conflict (id) do nothing;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position) values ('dbde67e8-21b6-461d-a6a8-b156c78a67e3', 'con-ganas', 'Con ganas', 'Sartén y cazo · 100 % seco', 'El nivel 2. Sigue siendo todo seco, pero toca encender el fuego: sartén, cazo y recetas que impresionan. Tú pones agua y un chorrito de aceite.', 2, 'hoja', '/demo/products/ramen-1.jpg', 2) on conflict (id) do nothing;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position) values ('e84bca92-d739-4733-b6c4-1abc04efe375', 'hambre-de-mas', 'Hambre de más', 'Recetas del mundo · con ingredientes frescos', 'El nivel 3. Ya sabes cocinar: este kit trae también los ingredientes frescos (carne, verdura, lácteos) y llega refrigerado.', 3, 'teja', '/demo/products/curry-1.jpg', 3) on conflict (id) do nothing;
insert into public.categories (id, slug, name, tagline, description, level, accent, image_url, position) values ('f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 'caja-sorpresa', 'Caja sorpresa', 'Un kit nuevo cada mes', 'No sabrás qué receta te toca hasta abrir la caja. Pago por adelantado de 1, 3 o 6 meses.', null, 'almendra', '/demo/products/sorpresa-1.jpg', 4) on conflict (id) do nothing;
insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('72475df3-538b-4bb6-9092-e4798f8a662c', 'kit-wraps-crujientes', 'Kit Wraps crujientes', 'Wraps de hummus y verduras crujientes. Sin fuego y sin nevera.', 'Tu primera receta sin encender nada. Tortillas de trigo que aguantan en la despensa, hummus que se prepara con agua en un minuto y verduras liofilizadas que crujen como recién cortadas. Enrollas, cortas y listo.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, null, 120, '{"minutes":15,"difficulty":1,"heat":"sin-fuego","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array['soja']::text[], array[]::text[], '{"youAdd":["100 ml de agua"],"steps":[{"title":"Prepara el hummus","text":"Echa el sobre de hummus en un bol, añade 100 ml de agua fría poco a poco y mezcla con un tenedor hasta que quede cremoso."},{"title":"Despierta las verduras","text":"Abre la bolsa de verduras liofilizadas y sacúdela con la mezcla de especias dentro. Quedan crujientes y con sabor."},{"title":"Unta las tortillas","text":"Extiende dos cucharadas de hummus en cada tortilla, dejando un dedo libre en el borde."},{"title":"Rellena y enrolla","text":"Reparte las verduras en una tira en el centro. Dobla los lados hacia dentro y enrolla apretando."},{"title":"Corta y a comer","text":"Corta cada wrap en diagonal con un cuchillo de sierra. Si no te los comes ya, envuélvelos en papel de horno."}],"tips":["Si el hummus queda espeso, añade agua a cucharaditas.","Calienta la tortilla 10 segundos en el microondas para que no se rompa al enrollar."]}'::jsonb, array['6 tortillas de trigo', 'Hummus en polvo (garbanzo y tahini)', 'Verduras crujientes liofilizadas', 'Mezcla de especias suave', 'Tarjeta de receta con QR']::text[], now() - interval '120 days', now() - interval '120 days') on conflict (id) do nothing;
