insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('a9371802-306a-4621-9509-c25cc6b33d33', 'kit-bowl-arcoiris', 'Kit Bowl arcoíris', 'Cuscús al microondas, garbanzos especiados y verduras de colores.', 'Un bowl que entra por los ojos y sale de la despensa. El cuscús se hace en el microondas en cinco minutos, los garbanzos vienen cocidos y listos para especiar y las verduras liofilizadas dan el color. El aliño de tahini lo une todo.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', true, true, null, 95, '{"minutes":15,"difficulty":1,"heat":"microondas","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["Agua (la misma cantidad que de cuscús)"],"steps":[{"title":"Cuscús al microondas","text":"Pon el cuscús en un bol apto para microondas con el mismo volumen de agua y una pizca de sal. Calienta 2 minutos, tapa con un plato y deja reposar 3."},{"title":"Especia los garbanzos","text":"Escurre y enjuaga los garbanzos del bote. Mézclalos con las especias tostadas."},{"title":"Hidrata las verduras","text":"Pon las verduras en un vaso con un poco de agua fría 2 minutos y escúrrelas."},{"title":"Monta el bowl","text":"Base de cuscús suelto con un tenedor, y encima, por zonas, garbanzos y verduras. Que se vean los colores."},{"title":"Aliña","text":"Mezcla el aliño de tahini con dos cucharadas de agua y riégalo por encima."}],"tips":["El bowl aguanta un día en la nevera: perfecto para llevar al instituto."]}'::jsonb, array['Cuscús', 'Garbanzos cocidos (bote)', 'Especias tostadas', 'Verduras liofilizadas', 'Aliño de tahini', 'Tarjeta de receta con QR']::text[], now() - interval '90 days', now() - interval '90 days') on conflict (id) do nothing;
