insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('beae607c-9233-4059-8699-6aa67c8de783', 'kit-parfait-frutos-rojos', 'Kit Parfait de frutos rojos', 'Crema de yogur que se monta con agua, granola y frutos rojos.', 'Capas de crema de yogur (viene en polvo y se monta con agua fría), granola con miel y frutos rojos liofilizados que recuperan todo su sabor. Montas cuatro tarros en diez minutos.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, 'Oferta', 80, '{"minutes":10,"difficulty":1,"heat":"sin-fuego","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua fría."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche', 'frutos-de-cascara']::text[], array[]::text[], array[]::text[], '{"youAdd":["200 ml de agua muy fría"],"steps":[{"title":"Monta la crema","text":"Mezcla el sobre de crema de yogur con 200 ml de agua muy fría y bate con unas varillas 2 minutos, hasta que espese."},{"title":"Primera capa","text":"Pon dos cucharadas de granola en el fondo de cada vaso o tarro."},{"title":"Crema y fruta","text":"Añade una capa de crema y unos frutos rojos. Repite hasta llenar."},{"title":"Remata","text":"Termina con granola, frutos rojos y una pizca de chía por encima."}],"tips":["Si lo dejas para mañana, guarda la granola aparte para que siga crujiente."]}'::jsonb, array['Crema de yogur en polvo', 'Granola con miel', 'Frutos rojos liofilizados', 'Semillas de chía', 'Tarjeta de receta con QR']::text[], now() - interval '60 days', now() - interval '60 days') on conflict (id) do nothing;
