insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('11711508-bff7-4893-8d40-de6e0e3c4111', 'kit-tostadas-aguacate', 'Kit Tostadas de guacamole', 'Guacamole liofilizado, pan crujiente y semillas con chile suave.', 'Guacamole hecho con aguacate liofilizado: se prepara con agua y sabe a recién hecho. Lo untas en pan de masa madre tostado y rematas con nuestra mezcla de semillas y chile suave.', '4431eb1f-361d-4afa-bd58-24ada8e7fef0', 1000, 'published', false, true, 'Nuevo', 12, '{"minutes":10,"difficulty":1,"heat":"sin-fuego","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'vegetariano']::text[], array['gluten', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["80 ml de agua","Opcional, como en la foto: un huevo cocido y unas hojas de espinaca"],"steps":[{"title":"Haz el guacamole","text":"Echa el guacamole en polvo en un bol y añade 80 ml de agua. Mezcla y deja reposar 2 minutos para que se hidrate."},{"title":"Prepara el pan","text":"Saca las rebanadas de pan tostado. Si te gusta templado, 20 segundos en el microondas."},{"title":"Unta","text":"Reparte el guacamole con una cuchara, sin miedo."},{"title":"Remata","text":"Espolvorea las semillas con chile y unas escamas de sal. ¡A comer!"}],"tips":["Para un toque ácido, añade unas gotas de limón si tienes en casa."]}'::jsonb, array['Pan de masa madre tostado', 'Guacamole liofilizado', 'Mezcla de semillas y chile suave', 'Escamas de sal', 'Tarjeta de receta con QR']::text[], now() - interval '6 days', now() - interval '6 days') on conflict (id) do nothing;
