insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('629ead1c-9bd7-4841-b3b5-9b7a000c741f', 'kit-ramen-casero', 'Kit Ramen casero', 'Caldo de miso, fideos ramen y toppings deshidratados. El que te convierte en chef.', 'Nuestro kit estrella y 100 % de despensa. Fideos ramen de verdad, caldo de miso, setas shiitake y cebolleta deshidratadas, alga nori y aceite de chile y sésamo. Un bol que no tiene nada que envidiar al de tu restaurante favorito.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, 'Más vendido', 340, '{"minutes":25,"difficulty":2,"heat":"cazo","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'soja', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["1 litro de agua (2 personas)","Opcional, para dejarlo como en la foto: huevos cocidos y gambas"],"steps":[{"title":"Hidrata las setas","text":"Pon las setas shiitake en un vaso con agua caliente del grifo 10 minutos. Guarda esa agua: tiene mucho sabor."},{"title":"Haz el caldo","text":"En un cazo, calienta el agua (incluida la de las setas). Cuando hierva, baja el fuego y disuelve el caldo de miso removiendo. Que no vuelva a hervir fuerte."},{"title":"Cuece los fideos","text":"En otro cazo con agua hirviendo, cuece los fideos 3 minutos. Escúrrelos y repártelos en los boles."},{"title":"Monta el bol","text":"Vierte el caldo caliente sobre los fideos. Añade las setas escurridas y la cebolleta."},{"title":"Toque final","text":"Pon un trozo de alga nori en el borde del bol y unas gotas de aceite de chile y sésamo. ¡Itadakimasu!"}],"tips":["Los fideos se cuecen aparte para que el caldo no quede turbio.","Más picante: más aceite de chile. Menos: solo sésamo."]}'::jsonb, array['Fideos ramen', 'Caldo de miso en polvo', 'Setas shiitake deshidratadas', 'Cebolleta liofilizada', 'Alga nori', 'Aceite de chile y sésamo', 'Tarjeta de receta con QR']::text[], now() - interval '150 days', now() - interval '150 days') on conflict (id) do nothing;
