insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('0c200051-60e5-4fc6-a384-c3bbeb69ff10', 'kit-tacos-al-pastor', 'Kit Tacos al pastor', 'Soja texturizada al pastor, tortillas de maíz y salsa de piña.', 'Tacos con soja texturizada marinada en adobo al pastor, hechos a la sartén. Textura de carne picada sin necesidad de nevera. El kit trae las tortillas de maíz y una salsa de piña con un punto picante.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', true, true, null, 175, '{"minutes":25,"difficulty":2,"heat":"sarten","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y un chorrito de aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'picante', 'sin-gluten']::text[], array['soja']::text[], array['gluten']::text[], array[]::text[], '{"youAdd":["300 ml de agua caliente","2 cucharadas de aceite"],"steps":[{"title":"Hidrata la soja","text":"Cubre la soja texturizada con agua caliente 10 minutos. Escúrrela apretando con una cuchara."},{"title":"Marina","text":"Mezcla la soja con el adobo al pastor y deja que coja sabor mientras calientas la sartén."},{"title":"Dora en la sartén","text":"Sartén a fuego medio-alto con el aceite. Saltea la soja 6-8 minutos hasta que se dore por los bordes."},{"title":"Calienta las tortillas","text":"En la misma sartén, ya sin aceite, 20 segundos por cada lado."},{"title":"Monta los tacos","text":"Tortilla, soja al pastor, salsa de piña y cebolla crujiente. Dobla y muerde."}],"tips":["Apila las tortillas calientes envueltas en un paño para que no se sequen."]}'::jsonb, array['Soja texturizada', 'Adobo al pastor', '12 tortillas de maíz', 'Salsa de piña y chile', 'Cebolla crujiente', 'Tarjeta de receta con QR']::text[], now() - interval '100 days', now() - interval '100 days') on conflict (id) do nothing;
