insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('5ebf0ff0-8228-4e27-953e-2f2622f77a85', 'kit-tortitas-americanas', 'Kit Tortitas americanas', 'Mezcla completa: solo añades agua. Esponjosas, altas y con sirope.', 'La mezcla ya lleva la leche y el huevo en polvo, así que solo añades agua. Te enseñamos a controlar el fuego de la sartén para que salgan doradas y altísimas. Incluye sirope de arce y pepitas de chocolate.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 210, '{"minutes":20,"difficulty":2,"heat":"sarten","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y un poco de aceite."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche', 'huevos']::text[], array['frutos-de-cascara']::text[], array[]::text[], '{"youAdd":["250 ml de agua","Unas gotas de aceite"],"steps":[{"title":"Haz la masa","text":"Mezcla la mezcla para tortitas con 250 ml de agua usando unas varillas. Que queden algunos grumitos: así salen más esponjosas."},{"title":"Reposo","text":"Deja la masa 5 minutos mientras se calienta la sartén a fuego medio-bajo."},{"title":"Engrasa poco","text":"Unas gotas de aceite repartidas con papel de cocina. La sartén debe brillar, no tener charco."},{"title":"Primera vuelta","text":"Vierte un cazo de masa. Cuando salgan burbujas en la superficie (1-2 minutos), dale la vuelta."},{"title":"Apila y decora","text":"Un minuto más y a la torre. Remata con sirope y pepitas de chocolate."}],"tips":["La primera tortita casi nunca sale bien: es la de prueba.","Si se queman por fuera y están crudas por dentro, baja el fuego."]}'::jsonb, array['Mezcla completa para tortitas', 'Sirope de arce', 'Pepitas de chocolate', 'Tarjeta de receta con QR']::text[], now() - interval '130 days', now() - interval '130 days') on conflict (id) do nothing;
