insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('6d81490b-c95a-487a-a88c-c70133745a78', 'kit-penne-arrabbiata', 'Kit Penne all''arrabbiata', 'La salsa de tomate picante más famosa de Roma.', 'Penne rigate de trigo duro, tomate triturado italiano y nuestra mezcla de guindilla y ajo deshidratado. Aprendes a sofreír sin quemar y a ligar la salsa con el agua de la pasta como en Italia.', 'dbde67e8-21b6-461d-a6a8-b156c78a67e3', 1000, 'published', false, true, null, 140, '{"minutes":20,"difficulty":2,"heat":"cazo","storage":"seco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite de oliva."},{"label":"Conservación","value":"Despensa: lugar fresco y seco. Consumo preferente: 6 meses desde el envío."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegano', 'picante']::text[], array['gluten']::text[], array[]::text[], array[]::text[], '{"youAdd":["2 litros de agua","3 cucharadas de aceite de oliva"],"steps":[{"title":"Agua a hervir","text":"Pon a hervir 2 litros de agua con una cucharada de sal en un cazo grande."},{"title":"Sofrito","text":"En una sartén, calienta el aceite a fuego bajo con el ajo y la guindilla 1 minuto. Si el ajo se tuesta demasiado, amarga."},{"title":"Salsa","text":"Añade el tomate triturado y cocina 10 minutos a fuego medio, removiendo de vez en cuando."},{"title":"Pasta","text":"Cuece los penne el tiempo del paquete menos un minuto. Antes de escurrir, guarda medio vaso del agua de cocción."},{"title":"Liga","text":"Echa la pasta a la salsa con un chorrito del agua guardada y remueve a fuego fuerte 1 minuto hasta que brille. Perejil y a la mesa."}],"tips":["El agua de la pasta tiene almidón: es lo que hace que la salsa se pegue."]}'::jsonb, array['Penne rigate', 'Tomate triturado italiano (brik)', 'Guindilla y ajo deshidratados', 'Perejil seco', 'Tarjeta de receta con QR']::text[], now() - interval '80 days', now() - interval '80 days') on conflict (id) do nothing;
