insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('0a53aa7d-4cf2-4f64-847a-ecd3b303d8ca', 'kit-butter-chicken', 'Kit Butter chicken con naan', 'Pollo fresco en salsa de tomate, mantequilla y garam masala.', 'El plato indio que gusta a todo el mundo. Llega refrigerado con los muslos de pollo, el yogur, la nata y la mantequilla; además, especias, tomate y la mezcla para hacer naan en la sartén. Nivel 3 porque hay que coordinar tres elaboraciones a la vez.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 150, '{"minutes":50,"difficulty":3,"heat":"sarten","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Agua."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'leche']::text[], array[]::text[], array[]::text[], '{"youAdd":["120 ml de agua (para el naan)"],"steps":[{"title":"Marina el pollo","text":"Corta el pollo en trozos y mézclalo con la mitad del yogur y las especias del marinado. Deja 15 minutos en la nevera."},{"title":"Masa de naan","text":"Mezcla la harina de naan con el resto del yogur y 120 ml de agua. Amasa 3 minutos y deja reposar tapada."},{"title":"Dora el pollo","text":"Sartén caliente con la mitad de la mantequilla. Dora el pollo 6 minutos y sácalo."},{"title":"La salsa","text":"En la misma sartén, el resto de la mantequilla, el tomate y el garam masala 3 minutos. Añade la nata y vuelve a meter el pollo 10 minutos a fuego suave."},{"title":"Naan a la sartén","text":"Divide la masa en bolas, estíralas finas y cocínalas en una sartén sin aceite muy caliente, 1 minuto por lado, hasta que hagan burbujas."},{"title":"Sirve","text":"Butter chicken en un bol y naan caliente al lado para mojar."}],"tips":["Con tres cosas a la vez, prepara todo antes de encender el fuego."]}'::jsonb, array['Muslos de pollo frescos', 'Yogur natural, nata y mantequilla', 'Garam masala y especias', 'Tomate concentrado', 'Mezcla para naan', 'Tarjeta de receta con QR']::text[], now() - interval '70 days', now() - interval '70 days') on conflict (id) do nothing;
