insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('c4cf16d7-722c-4932-a9b3-d2fdc678c730', 'kit-gyozas-caseras', 'Kit Gyozas caseras', 'Obleas frescas, relleno de cerdo y col, y salsa ponzu.', 'El reto del nivel 3: cerrar gyozas con sus pliegues. Llega refrigerado con las obleas, la carne picada y la col; además, especias para el relleno y salsa ponzu para mojar. Te enseñamos el pliegue y la técnica de vapor y sartén.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, 'Nuevo', 18, '{"minutes":60,"difficulty":3,"heat":"sarten","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Agua y aceite."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array[]::text[], array['gluten', 'soja', 'sesamo']::text[], array[]::text[], array[]::text[], '{"youAdd":["Un vasito de agua","1 cucharada de aceite"],"steps":[{"title":"Relleno","text":"Pica la col y la cebolleta muy finas. Mézclalas con la carne y las especias hasta que quede una pasta."},{"title":"Rellena","text":"Pon una cucharadita de relleno en el centro de cada oblea y moja el borde con un dedo húmedo."},{"title":"El pliegue","text":"Dobla por la mitad y, desde un extremo, haz 5 o 6 pliegues en la cara de delante, apretando contra la de detrás."},{"title":"Dora","text":"Sartén con aceite a fuego medio. Coloca las gyozas de pie y dóralas 2 minutos por la base."},{"title":"Vapor","text":"Echa medio vaso de agua y tapa enseguida (¡cuidado con las salpicaduras!). Cocina 6 minutos hasta que se evapore el agua."},{"title":"Sirve","text":"Con la base crujiente hacia arriba y ponzu con sésamo para mojar."}],"tips":["Las primeras quedan feas: a la décima te salen perfectas.","Puedes congelarlas crudas y cocinarlas otro día."]}'::jsonb, array['30 obleas para gyozas', 'Carne picada de cerdo fresca', 'Col y cebolleta frescas', 'Especias para el relleno', 'Salsa ponzu', 'Aceite de sésamo', 'Tarjeta de receta con QR']::text[], now() - interval '9 days', now() - interval '9 days') on conflict (id) do nothing;
