insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('6c0cf2f9-8833-4fa4-8699-8cbb8feb3e5e', 'kit-pizza-napolitana', 'Kit Pizza napolitana', 'Masa de larga fermentación, mozzarella fresca y albahaca.', 'Harina tipo 00, levadura y tomate San Marzano, más los frescos: mozzarella fior di latte y albahaca. Estiras a mano, horneas a máxima potencia y consigues un borde inflado y tostado.', 'e84bca92-d739-4733-b6c4-1abc04efe375', 1000, 'published', false, true, null, 260, '{"minutes":45,"difficulty":3,"heat":"horno","storage":"fresco"}'::jsonb, '[{"label":"Tú pones","value":"Agua templada y aceite de oliva."},{"label":"Tiempo de reposo","value":"La masa necesita entre 8 y 24 horas de reposo en nevera."},{"label":"Conservación","value":"Llega refrigerado. Guarda los frescos en la nevera nada más recibirlo y cocínalo en 3 días."},{"label":"Receta","value":"Tarjeta con QR: escanéalo y verás la receta paso a paso en el móvil."}]'::jsonb, array['vegetariano']::text[], array['gluten', 'leche']::text[], array[]::text[], array[]::text[], '{"youAdd":["300 ml de agua templada","1 cucharada de aceite de oliva"],"steps":[{"title":"La masa (el día antes)","text":"Mezcla la harina, la levadura, una cucharadita de sal y el agua templada. Amasa 10 minutos hasta que esté lisa, haz bolas y guárdalas tapadas en la nevera de 8 a 24 horas."},{"title":"Atempera","text":"Saca las bolas de la nevera 1 hora antes y pon el horno a la máxima temperatura con la bandeja dentro."},{"title":"Estira a mano","text":"Aplasta la bola desde el centro hacia fuera, dejando el borde gordito. Nada de rodillo: aplastaría el aire."},{"title":"Monta","text":"Tomate aplastado con la mano, mozzarella escurrida y troceada, un chorrito de aceite."},{"title":"Hornea","text":"Sobre la bandeja caliente, 7-9 minutos hasta que el borde esté inflado y con manchas tostadas."},{"title":"Albahaca","text":"Al sacarla, unas hojas de albahaca fresca. Corta y comparte (o no)."}],"tips":["Usa guantes de horno para sacar la bandeja: está ardiendo."]}'::jsonb, array['Harina tipo 00', 'Levadura seca', 'Tomate San Marzano', 'Mozzarella fior di latte fresca', 'Albahaca fresca', 'Tarjeta de receta con QR']::text[], now() - interval '140 days', now() - interval '140 days') on conflict (id) do nothing;
