insert into public.products (id, slug, name, subtitle, description, category_id, tax_rate_bps, status, is_featured, is_demo, badge, sales_count, attributes, specs, tags, allergens, allergen_traces, recipe_allergens, recipe, includes, published_at, created_at) values ('801b9aff-7671-4c0c-9f6f-d469714e5aa6', 'caja-sorpresa', 'Caja sorpresa', 'Un kit nuevo cada mes. No sabrás cuál hasta abrir la caja.', 'Cada mes enviamos un kit distinto con recetas que no están en la tienda. Las cajas de 1 y 3 meses son de niveles 1 y 2 (100 % secas); la de 6 meses incluye un kit de nivel 3 con frescos. Pagas por adelantado y la recibes la primera semana de cada mes. No se renueva sola.', 'f1cef13a-c34d-4a27-bfd1-cb848b558ac9', 1000, 'published', true, true, null, 64, '{"minutes":40,"difficulty":2,"heat":"sarten","storage":"seco"}'::jsonb, '[{"label":"Envíos","value":"La primera semana de cada mes, a la misma dirección."},{"label":"Renovación","value":"Sin renovación automática."},{"label":"Alérgenos","value":"Variables según el kit. Te avisamos por email antes de cada envío."}]'::jsonb, array[]::text[], array[]::text[], array[]::text[], array[]::text[], '{"youAdd":["Depende del kit del mes"],"steps":[{"title":"Abre la caja","text":"Dentro encontrarás el kit del mes y su tarjeta con un QR propio."},{"title":"Escanea su QR","text":"Cada kit sorpresa trae su propia receta paso a paso."},{"title":"Colecciona","text":"Pega la pegatina de nivel en tu tarjeta de progreso."}],"tips":["Si tienes alguna alergia, indícanoslo al comprar y adaptamos la caja."]}'::jsonb, array['Un kit sorpresa al mes', 'Receta exclusiva con QR', 'Pegatina de nivel para coleccionar']::text[], now() - interval '30 days', now() - interval '30 days') on conflict (id) do nothing;
